package threadctx

import (
	_ "embed"
	"strings"
)

// The common-word list the masker reads, generated by cmd/gen-mask-words from
// vendored sources; the file's header states its sources, their licenses and
// the command that regenerates it.
var (
	//go:embed common_words.txt
	commonWordsFile string

	// commonWords are the common English words, contractions included.
	commonWords = wordSet(commonWordsFile)
)

func wordSet(file string) map[string]bool {
	out := map[string]bool{}
	for line := range strings.Lines(file) {
		line = strings.TrimSpace(line)
		if line != "" && !strings.HasPrefix(line, "#") {
			out[line] = true
		}
	}
	return out
}
